package android.content;import java.util.*;public class SharedPreferences {final Map<String,Object> values=new HashMap<>();public synchronized boolean getBoolean(String k,boolean d){Object v=values.get(k);return v instanceof Boolean?(Boolean)v:d;}public synchronized long getLong(String k,long d){Object v=values.get(k);return v instanceof Number?((Number)v).longValue():d;}public Editor edit(){return new Editor();}public class Editor{final Map<String,Object> updates=new HashMap<>();public Editor putBoolean(String k,boolean v){updates.put(k,v);return this;}public Editor putLong(String k,long v){updates.put(k,v);return this;}public boolean commit(){synchronized(SharedPreferences.this){values.putAll(updates);}return true;}}}
